// Evaluate two edges at the same band limits with the original operation
// order in every lane. Geometry preparation and drawing share this kernel.
[System.Runtime.CompilerServices.MethodImpl(System.Runtime.CompilerServices.MethodImplOptions.AggressiveInlining)]
private static (double FirstTop, double FirstBottom, double SecondTop, double SecondBottom)
    PairEndpoints(in Edge first, in Edge second, double top, double bottom)
{
    if (System.Runtime.Intrinsics.X86.Avx.IsSupported)
    {
        var y = System.Runtime.Intrinsics.Vector256.Create(top, bottom, top, bottom);
        var originY = System.Runtime.Intrinsics.Vector256.Create(first.originY, first.originY, second.originY, second.originY);
        var deltaY = System.Runtime.Intrinsics.Vector256.Create(first.deltaY, first.deltaY, second.deltaY, second.deltaY);
        var fraction = System.Runtime.Intrinsics.X86.Avx.Divide(System.Runtime.Intrinsics.X86.Avx.Subtract(y, originY), deltaY);
        var deltaX = System.Runtime.Intrinsics.Vector256.Create(first.deltaX, first.deltaX, second.deltaX, second.deltaX);
        var product = System.Runtime.Intrinsics.X86.Avx.Multiply(deltaX, fraction);
        var originX = System.Runtime.Intrinsics.Vector256.Create(first.originX, first.originX, second.originX, second.originX);
        var result = System.Runtime.Intrinsics.X86.Avx.Add(originX, product);
        return (System.Runtime.Intrinsics.Vector256.GetElement(result, 0), System.Runtime.Intrinsics.Vector256.GetElement(result, 1),
            System.Runtime.Intrinsics.Vector256.GetElement(result, 2), System.Runtime.Intrinsics.Vector256.GetElement(result, 3));
    }
    var a = first.Endpoints(top, bottom); var b = second.Endpoints(top, bottom);
    return (a.Top, a.Bottom, b.Top, b.Bottom);
}

private readonly record struct Curve(Point A, Point C, Point B, int Depth);
